CREATE TABLE threads (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id), creator_id TEXT NOT NULL REFERENCES principals(id), title TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX threads_room ON threads(room_id,id);
CREATE TABLE message_links (message_id TEXT PRIMARY KEY REFERENCES messages(id), thread_id TEXT NOT NULL REFERENCES threads(id), reply_to_message_id TEXT REFERENCES messages(id));
CREATE INDEX message_links_thread ON message_links(thread_id,message_id);
CREATE TABLE message_revisions (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id), version INTEGER NOT NULL CHECK(version>=2), editor_id TEXT NOT NULL REFERENCES principals(id), text TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ('text','markdown')), created_at TEXT NOT NULL, UNIQUE(message_id,version));
CREATE TABLE room_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, room_id TEXT NOT NULL REFERENCES rooms(id), kind TEXT NOT NULL, message_id TEXT REFERENCES messages(id), version INTEGER, thread_id TEXT REFERENCES threads(id), actor_id TEXT NOT NULL REFERENCES principals(id), created_at TEXT NOT NULL);
CREATE INDEX room_events_room_seq ON room_events(room_id,seq);
CREATE INDEX room_events_revision ON room_events(message_id,version);
CREATE TABLE page_tokens (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), room_id TEXT NOT NULL REFERENCES rooms(id), kind TEXT NOT NULL, scope_json TEXT NOT NULL CHECK(json_valid(scope_json)), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), created_at TEXT NOT NULL);
CREATE TABLE inbox_state (principal_id TEXT NOT NULL REFERENCES principals(id), room_id TEXT NOT NULL REFERENCES rooms(id), acked_seq INTEGER NOT NULL DEFAULT 0 CHECK(acked_seq>=0), PRIMARY KEY(principal_id,room_id));
CREATE TABLE g2_audit (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), room_id TEXT NOT NULL REFERENCES rooms(id), operation TEXT NOT NULL, target_id TEXT NOT NULL, version INTEGER, created_at TEXT NOT NULL);
CREATE VIEW message_history AS SELECT m.seq AS message_seq,m.id AS message_id,m.room_id,m.actor_id,m.actor_id AS editor_id,1 AS version,m.text,m.format,m.created_at,l.thread_id,l.reply_to_message_id FROM messages m LEFT JOIN message_links l ON l.message_id=m.id UNION ALL SELECT m.seq,m.id,m.room_id,m.actor_id,r.editor_id,r.version,r.text,r.format,r.created_at,l.thread_id,l.reply_to_message_id FROM message_revisions r JOIN messages m ON m.id=r.message_id LEFT JOIN message_links l ON l.message_id=m.id;
CREATE VIEW message_current AS SELECT h.message_seq AS seq,h.message_id AS id,h.room_id,h.actor_id,h.editor_id,h.version,h.text,h.format,h.created_at,h.thread_id,h.reply_to_message_id FROM message_history h WHERE h.version=(SELECT max(v.version) FROM message_history v WHERE v.message_id=h.message_id);
CREATE TRIGGER links_valid BEFORE INSERT ON message_links WHEN NOT EXISTS (SELECT 1 FROM messages m JOIN threads t ON t.id=NEW.thread_id WHERE m.id=NEW.message_id AND m.room_id=t.room_id AND (NEW.reply_to_message_id IS NULL OR EXISTS (SELECT 1 FROM messages p JOIN message_links l ON l.message_id=p.id WHERE p.id=NEW.reply_to_message_id AND p.room_id=m.room_id AND l.thread_id=t.id AND p.id!=m.id))) BEGIN SELECT RAISE(ABORT,'invalid message relation'); END;
CREATE TRIGGER revision_valid BEFORE INSERT ON message_revisions WHEN NOT EXISTS (SELECT 1 FROM messages m WHERE m.id=NEW.message_id AND m.actor_id=NEW.editor_id AND NEW.version=COALESCE((SELECT max(version) FROM message_revisions WHERE message_id=m.id),1)+1) BEGIN SELECT RAISE(ABORT,'invalid revision'); END;
CREATE TRIGGER event_message AFTER INSERT ON messages BEGIN INSERT INTO room_events(id,room_id,kind,message_id,version,actor_id,created_at) VALUES ('message:'||NEW.id,NEW.room_id,'message.posted',NEW.id,1,NEW.actor_id,NEW.created_at); END;
CREATE TRIGGER event_revision AFTER INSERT ON message_revisions BEGIN INSERT INTO room_events(id,room_id,kind,message_id,version,actor_id,created_at) SELECT 'revision:'||NEW.id,m.room_id,'message.revised',m.id,NEW.version,NEW.editor_id,NEW.created_at FROM messages m WHERE m.id=NEW.message_id; END;
CREATE TRIGGER event_thread AFTER INSERT ON threads BEGIN INSERT INTO room_events(id,room_id,kind,thread_id,actor_id,created_at) VALUES ('thread:'||NEW.id,NEW.room_id,'thread.created',NEW.id,NEW.creator_id,NEW.created_at); END;
CREATE TRIGGER threads_no_update BEFORE UPDATE ON threads BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER threads_no_delete BEFORE DELETE ON threads BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER links_no_update BEFORE UPDATE ON message_links BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER links_no_delete BEFORE DELETE ON message_links BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER revisions_no_update BEFORE UPDATE ON message_revisions BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER revisions_no_delete BEFORE DELETE ON message_revisions BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER events_no_update BEFORE UPDATE ON room_events BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON room_events BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER tokens_no_update BEFORE UPDATE ON page_tokens BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER tokens_no_delete BEFORE DELETE ON page_tokens BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER g2_audit_no_update BEFORE UPDATE ON g2_audit BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER g2_audit_no_delete BEFORE DELETE ON g2_audit BEGIN SELECT RAISE(ABORT,'immutable'); END;
